/**
 * @method
 * @name predictfun#fetchMarkets
 * @description Retrieves all outcome markets from outcomeMeta.
 * Each binary outcome becomes one CCXT prediction market with two outcomes: YES and NO.
 * @see https://dev.predict.fun/get-categories-25326910e0
 * @see https://dev.predict.fun/search-categories-and-markets-27399810e0
 * @param {object} [params] extra parameters
 * @param {string} [params.query] a single search term — routes the call through the search endpoint and returns only the matching markets
 * @param {string[]} [params.queries] multiple search terms (alternative to query), the results are merged and deduplicated
 * @param {string[]} [params.tags] predictfun tag ids
 * @param {string} [params.slug] direct lookup by event slug
 * @param {int} [params.limit] the maximum number of events to collect markets from
 * @returns {ccxt.Market[]} array of market structures
 */
func (this *Predictfun) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Predictfun) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	events := (<-this.FetchEventsAsync(params))
	ccxt.PanicOnError(events)
	var eventsLength int = ccxt.GetArrayLength(events)
	var markets []any = []any{}
	for ei := 0; ei < eventsLength; ei++ {
		var eventMarkets []any = ccxt.SafeListTyped(ccxt.GetValue(events, ei), "markets")
		var eventMarketsLength int = len(eventMarkets)
		for mi := 0; mi < eventMarketsLength; mi++ {
			markets = append(markets, func() any {
				if mi >= 0 && mi < len(eventMarkets) {
					return ccxt.DerefScalar(eventMarkets[mi])
				}
				return nil
			}())
		}
	}

	ch <- markets
	return nil
}

/**
 * @method
 * @name predictfun#fetchEvent
 * @description fetches a single prediction-market event (market topic)
 * @see https://dev.predict.fun/get-category-by-slug-25326911e0
 * @param {string} id event slug
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.slug] event slug, overrides the id argument when both are given
 * @returns {object} a [prediction event structure](https://docs.ccxt.com/#/?id=prediction-event-structure)
 */
func (this *Predictfun) FetchEventAsync(id any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchEventBody(ch, id, optionalArgs...)
	return ch
}
func (this *Predictfun) fetchEventBody(ch chan any, id any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// the id argument is the event slug, per the base fetchEvent (id) contract - params.slug
	// overrides it so a caller can pass the slug the same way fetchEvents () takes it
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var paramSlug *string = this.SafeString(params, "slug")
	var slug any = id
	if paramSlug != nil {
		slug = paramSlug
	}
	if ccxt.IsEqual(slug, nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " fetchEvent() requires the \"id\" argument or the \"slug\" parameter"))
	}

	events := (<-this.FetchEventsAsync(this.Extend(map[string]any{
		"slug": slug,
	}, params)))
	ccxt.PanicOnError(events)

	ch <- this.SafeDict(events, 0)
	return nil
}

