		//                         "question": "Ethereum Up or Down - August 27, 10AM-10:15AM ET",
		//                         "questionIndex": null,
		//                         "resolution": null,
		//                         "resolverAddress": "0x77620FAb2969dF2D5696F1f081940E416Cf17cA5",
		//                         "rewards": {
		//                             "current": null,
		//                             "schedule": [
		//                                 {
		//                                     "endsAt": "2026-08-27T14:15:00.000Z",
		//                                     "hourlyRate": 3000,
		//                                     "startsAt": "2026-08-27T14:00:00.000Z"
		//                                 }
