/**
 * @method
 * @name predictfun#cancelOrders
 * @description removes several of your own orders from the order book, up to a hundred at a time
 * @see https://dev.predict.fun/remove-orders-by-hash-38139973e0
 * @param {string[]} ids the order hashes, as returned by createOrder
 * @param {string} [outcome] unified outcome handle the orders belong to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [order structures](https://docs.ccxt.com/#/?id=order-structure)
 */
func (this *Predictfun) CancelOrdersAsync(ids any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.cancelOrdersBody(ch, ids, optionalArgs...)
	return ch
}
func (this *Predictfun) cancelOrdersBody(ch chan any, ids any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcome *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = outcome
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var outcomeObj any = nil
	if outcome != nil {

		ccxt.PanicOnError((<-this.LoadOutcomeAsync(outcome)))
		outcomeObj = this.Outcome(outcome)
	}
	var idsLength int = ccxt.GetArrayLength(ids)
	if idsLength == 0 {
		panic(ccxt.ArgumentsRequired(this.Id + " cancelOrders() requires at least one order hash"))
	}
	if idsLength > 100 {
		panic(ccxt.BadRequest(this.Id + " cancelOrders() takes at most 100 order hashes per call"))
	}
	// the JWT identifies the signer whose orders may be pulled

	ccxt.PanicOnError((<-this.AuthenticateAsync()))
	var request map[string]any = map[string]any{
		"data": map[string]any{
			"hashes": ids,
		},
	}
	// this only pulls the orders off the book, it does not cancel them on chain

	response := (<-this.PredictfunPostV1OrdersRemoveByHash(this.Extend(request, params))).Raw
	ccxt.PanicOnError(response)
	//
	//     {
	//         "removed": [ "0xebf11bdff189b8609c9ae66bebb20b94742865a2d94970856f3fb6b0896f9ec0" ],
	//         "rejected": [],
	//         "noop": [ "0x00de1b3b4d8647c371022c3b952c82d89298ed3746d4677e582ef9808bbdc6cf" ],
	//         "success": true
	//     }
	//
	var rejected any = this.SafeList(response, "rejected", []any{})
	var rejectedLength int = ccxt.GetArrayLength(rejected)
	if rejectedLength > 0 {
		panic(ccxt.OrderNotFound(ccxt.Add(this.Id+" cancelOrders() was refused for ", this.Json(rejected))))
	}
	// the venue reports hashes only, so each one becomes a row the shared order parser can
	// read: it takes the hash off orderHash and the status through parseOrderStatus
	var removed []any = ccxt.SafeListTyped(response, "removed")
	var noop []any = ccxt.SafeListTyped(response, "noop")
	var rows []any = []any{}
	var removedLength int = len(removed)
	for i := 0; i < removedLength; i++ {
		rows = append(rows, this.Extend(response, map[string]any{
			"orderHash": func() any {
				if i >= 0 && i < len(removed) {
					return ccxt.DerefScalar(removed[i])
				}
				return nil
			}(),
			"status": "CANCELLED",
		}))
	}
	var noopLength int = len(noop)
	for i := 0; i < noopLength; i++ {
		// accepted, but nothing was resting to pull: the order had already filled, expired,
		// was never booked, or had been removed before - so the status is left unknown
		rows = append(rows, this.Extend(response, map[string]any{
			"orderHash": func() any {
				if i >= 0 && i < len(noop) {
					return ccxt.DerefScalar(noop[i])
				}
				return nil
			}(),
		}))
	}

	ch <- this.ParsePredictionOrders(rows, outcomeObj)
	return nil
}

